  border-left: 1px solid var(--color-border-primary-default);
  border-right: none;
  line-height: 22px;
  padding: 12px 15px;
  font-size: 14px;
  color: var(--color-text-primary-default);
  transition: border-color 0.3s ease-out, background 0.3s ease;
