/**
* Use inter-font instead of normal font for popover. Also add the new variables to this file.
*/
.mt-popover-item {
  display: flex;
  flex-direction: column;
  color: var(--color-text-primary-default);
  padding: 8px 0;
}
.mt-popover-item * {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "San Francisco", "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
}
@supports (font-variation-settings: normal) {
.mt-popover-item * {
    font-family: "Inter var", -apple-system, BlinkMacSystemFont, "San Francisco", "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
    font-feature-settings: "ss01" on, "ss02" on, "case" on, "cpsp" on, "zero" on, "cv09" on, "cv07" on, "cv06" on, "cv10" on, "cv11" on;
}
}
.mt-popover-item.mt-popover-item--clickable {
  cursor: pointer;
}
.mt-popover-item.mt-popover-item--clickable:hover {
  position: relative;
}
.mt-popover-item.mt-popover-item--clickable:hover::before {
  content: "";
}
.mt-popover-item:hover::before {
  position: absolute;
  background-color: var(--color-interaction-secondary-hover);
  border-radius: 4px;
  top: 4px;
  right: -8px;
  bottom: 4px;
  left: -8px;
  pointer-events: none;
}
.mt-popover-item.is--draggable {
  cursor: grab;
}
.mt-popover-item--critical {
