.is--drag-element {
  position: absolute;
  pointer-events: none;
  touch-action: none;
  user-focus: none;
  user-select: none;
  z-index: 1400;
  box-shadow: 0 0 4px 0 #189eff;
  overflow: hidden;
  cursor: grab;
}
.is--drag-element > * {
  user-focus: none;
  user-select: none;
  user-input: none;
  user-modify: none;
  pointer-events: none;
  touch-action: none;
  -webkit-user-drag: none;
}
.is--drag-element.is--valid-drag {
  box-shadow: 0 0 4px 0 #37d046;
}
.is--drag-element.is--invalid-drag {
  box-shadow: 0 0 4px 0 #de294c;
}
.is--draggable {
  user-focus: none;
  user-select: none;
  cursor: grab;
}
.is--draggable img {
  user-focus: none;
  user-select: none;
  user-input: none;
  user-modify: none;
  pointer-events: none;
  touch-action: none;
  -webkit-user-drag: none;
}
.is--dragging {
  background: #f0f2f5;
  border: 1px dashed #d1d9e0;
  box-shadow: none;
  color: #f0f2f5;
  cursor: grab;
}
.is--dragging > * {
  opacity: 0;
}
